def sigma_moe_top2_route(h_norm: np.ndarray, router_w: np.ndarray, super_w: np.ndarray):
    pooled = np.mean(h_norm, axis=0)
    gates = 1.0 / (1.0 + np.exp(-np.dot(router_w, pooled) * float(np.dot(super_w[0], pooled))))
    top2_idx = np.argsort(-gates)[:2]
    return top2_idx, gates[top2_idx] / np.sum(gates[top2_idx])

def de_doppler_taylor_tree_snr(spectrogram: np.ndarray, drift_hz_s: float = 0.1494) -> float:
    integrated = np.mean(spectrogram, axis=0)
    noise_mad = np.median(np.abs(integrated - np.median(integrated))) * 1.4826
    return float((np.max(integrated) - np.median(integrated)) / max(1e-9, noise_mad))

def compute_plddt_confidence(contact_logits: np.ndarray) -> float:
    probs = np.exp(contact_logits) / np.sum(np.exp(contact_logits), axis=-1, keepdims=True)
    bins = np.linspace(2.5, 97.5, probs.shape[-1])
    return float(np.mean(np.sum(probs * bins, axis=-1)))

def multi_krum_select(gradients: list[np.ndarray], f_byzantine: int = 3) -> int:
    n = len(gradients)
    k = n - f_byzantine - 2
    scores = [sum( sorted(np.linalg.norm(g - o)**2 for o in gradients)[1:k+1] ) for g in gradients]
    return int(np.argmin(scores))
